470:   void setMockResponse(String response) {
471:     _mockedResponse = response;
472:   }
473:   
474:   @override
475:   Future<String> fetchData() async => _mockedResponse ?? 'default mock';
476: }
477: 
478: // Test
479: test('uses manual mock', () async {
480:   final mockService = MockApiService();
