206: 
207: ### Custom Matchers
208: 
209: ```dart
210: import 'package:test/test.dart';
211: 
212: class HasLength extends Matcher {
213:   final int expectedLength;
214:   HasLength(this.expectedLength);
215:   
216:   @override
217:   bool matches(item, Map matchState) {
218:     return (item as List).length == expectedLength;
219:   }
220:   
221:   @override
222:   Description describe(Description description) {
223:     return description.add('has length $expectedLength');
224:   }
225: }
226: 
227: // Usage
228: test('list has custom length', () {
229:   final list = [1, 2, 3];
230:   expect(list, HasLength(3));
231: });
232: ```
