35: ## Dart Unit Tests
36: 
37: ### Basic Plugin Unit Test
38: 
39: ```dart
40: import 'package:flutter_test/flutter_test.dart';
41: import 'package:my_plugin/my_plugin.dart';
42: 
43: void main() {
44:   test('plugin initializes correctly', () {
45:     final plugin = MyPlugin();
46:     expect(plugin.initialized, false);
47:     
48:     plugin.initialize();
49:     expect(plugin.initialized, true);
50:   });
51:   
52:   test('processes data correctly', () {
53:     final plugin = MyPlugin();
54:     final result = plugin.processData([1, 2, 3]);
55:     
56:     expect(result, [2, 4, 6]);
57:   });
58: }
59: ```
60: 
61: ### Mocking Platform Channels in Unit Tests
62: 
63: ```dart
64: import 'package:flutter/services.dart';
65: import 'package:flutter_test/flutter_test.dart';
66: import 'package:my_plugin/my_plugin.dart';
67: 
68: void main() {
69:   TestWidgetsFlutterBinding.ensureInitialized();
70:   
71:   late MyPlugin plugin;
72:   
73:   setUp(() {
74:     // Mock platform channel
75:     TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
76:         .setMockMethodCallHandler(
77:       const MethodChannel('com.example.my_plugin'),
78:       (MethodCall methodCall) async {
79:         if (methodCall.method == 'getNativeValue') {
80:           return 42;
81:         }
82:         return null;
83:       },
84:     );
85:     
86:     plugin = MyPlugin();
87:   });
88:   
89:   tearDown(() {
90:     TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
91:         .setMockMethodCallHandler(
92:       const MethodChannel('com.example.my_plugin'),
93:       null,
94:     );
95:   });
96:   
97:   test('gets value from native side', () async {
98:     final result = await plugin.getNativeValue();
99:     expect(result, 42);
100:   });
101: }
102: ```
