352: 
353: ### Native Error Handling
354: 
355: ```dart
356: testWidgets('handles native errors', (tester) async {
357:   TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
358:       .setMockMethodCallHandler(
359:     const MethodChannel('com.example.my_plugin'),
360:     (MethodCall methodCall) async {
361:       if (methodCall.method == 'failingMethod') {
362:         throw PlatformException(
363:           code: 'ERROR',
364:           message: 'Native error occurred',
365:         );
366:       }
367:       return null;
368:     },
369:   );
370:   
371:   final plugin = MyPlugin();
372:   
373:   expect(
374:     () => plugin.failingMethod(),
375:     throwsA(isA<PlatformException>()),
376:   );
377: });
378: ```
